// File was entirely generated by Claude
// Tests for linalg/matrix.hpp: construction, element access and the matrix product.
// Uses int (and small float values) so all results are exact and can be compared with ==.

#ifdef NDEBUG
#error "Tests rely on assert(); build without NDEBUG (e.g. a Debug build)."
#endif

#include <cassert>
#include <cstddef>
#include <iostream>
#include "linalg/matrix.hpp"
#include "linalg/matrix_io.hpp"
using namespace linalg;

// Element-wise comparison via the two-index operator[]
template<typename T, std::size_t R, std::size_t C>
bool equal(Matrix<T, R, C> a, Matrix<T, R, C> b)
{
    for (std::size_t i = 0; i < R; i++)
        for (std::size_t j = 0; j < C; j++)
            if (a[i, j] != b[i, j]) return false;
    return true;
}

void test_default_is_zero()
{
    Matrix<int, 3, 4> z;
    for (std::size_t i = 0; i < 3; i++)
        for (std::size_t j = 0; j < 4; j++)
            assert((z[i, j] == 0));
}

void test_construction_and_access()
{
    // Non-square on purpose: a swapped row/column index cannot go unnoticed
    Matrix<int, 2, 3> a{{{{1, 2, 3}, {4, 5, 6}}}};
    assert((a[0, 0] == 1)); assert((a[0, 1] == 2)); assert((a[0, 2] == 3));
    assert((a[1, 0] == 4)); assert((a[1, 1] == 5)); assert((a[1, 2] == 6));
}

void test_flat_index_is_row_major()
{
    Matrix<int, 2, 3> a{{{{1, 2, 3}, {4, 5, 6}}}};
    for (std::size_t k = 0; k < 6; k++)
        assert(a[k] == static_cast<int>(k) + 1);
}

void test_write_access()
{
    Matrix<int, 2, 3> a;
    a[1, 2] = 42;
    assert((a[1, 2] == 42));
    assert(a[5] == 42);             // same element through the flat index
    assert((a[0, 0] == 0));         // nothing else changed
}

void test_addition()
{
    Matrix<int, 2, 3> a{{{{1, 2, 3}, {4, 5, 6}}}};
    Matrix<int, 2, 3> b{{{{0, 5, 6}, {8, 9, 1}}}};
    Matrix<int, 2, 3> expected{{{{1, 7, 9}, {12, 14, 7}}}};
    assert(equal(a+b, expected));
}

void test_subtraction()
{
    Matrix<int, 2, 3> a{{{{1, 2, 3}, {4, 5, 6}}}};
    Matrix<int, 2, 3> b{{{{0, 5, 6}, {8, 9, 1}}}};
    Matrix<int, 2, 3> expected{{{{1, -3, -3}, {-4, -4, -5}}}};
    assert(equal(a-b, expected));
}

void test_product_non_square()
{
    Matrix<int, 2, 3> a{{{{1, 2, 3}, {4, 5, 6}}}};
    Matrix<int, 3, 2> b{{{{7, 8}, {9, 10}, {11, 12}}}};
    Matrix<int, 2, 2> expected{{{{58, 64}, {139, 154}}}};   // computed by hand
    assert(equal(a * b, expected));
}

void test_product_order_matters()
{
    // A*B != B*A: catches implementations that mix up which factor is which
    Matrix<int, 2, 2> a{{{{1, 2}, {3, 4}}}};
    Matrix<int, 2, 2> b{{{{0, 1}, {1, 0}}}};          
    Matrix<int, 2, 2> ab{{{{2, 1}, {4, 3}}}};
    Matrix<int, 2, 2> ba{{{{3, 4}, {1, 2}}}};
    assert(equal(a * b, ab));
    assert(equal(b * a, ba));
}

void test_identity()
{
    Matrix<int, 3, 3> id{{{{1, 0, 0}, {0, 1, 0}, {0, 0, 1}}}};
    Matrix<int, 3, 3> a{{{{2, -1, 4}, {0, 3, 5}, {7, 1, -2}}}};
    assert(equal(id * a, a));
    assert(equal(a * id, a));
}

void test_matrix_vector()
{
    Matrix<int, 2, 3> a{{{{1, 2, 3}, {4, 5, 6}}}};
    Vector<int, 3> v{{{{1}, {0}, {-1}}}};
    Vector<int, 2> r = a * v;
    assert(r[0] == -2);             // 1*1 + 2*0 + 3*(-1)
    assert(r[1] == -2);             // 4*1 + 5*0 + 6*(-1)
}

void test_vector_indexing()
{
    Vector<int, 4> v{{{10, 20, 30, 40}}};
    for (std::size_t k = 0; k < 4; k++)
        assert((v[k] == v[k, 0]));
    assert(v[3] == 40);
}

void test_float_product()
{
    // Small values that are exact in float, so == is safe here
    Matrix<float, 2, 2> a{{{{0.5f, 2.0f}, {-1.0f, 0.25f}}}};
    std::cout << "Matrix a:\n"; 
    std::cout << a;
    Matrix<float, 2, 2> b{{{{4.0f, 0.0f}, {1.0f, 8.0f}}}};
    std::cout << "Matrix b:\n";
    std::cout << b;
    Matrix<float, 2, 2> expected{{{{4.0f, 16.0f}, {-3.75f, 2.0f}}}};
    std::cout << "Product a*b:\n";
    std::cout << a*b;
    assert(equal(a * b, expected));
}

int main()
{
    test_default_is_zero();
    test_construction_and_access();
    test_flat_index_is_row_major();
    test_write_access();
    test_addition();
    test_product_non_square();
    test_product_order_matters();
    test_identity();
    test_matrix_vector();
    test_vector_indexing();
    test_float_product();
    std::cout << "All matrix tests passed\n";
    return 0;
}